mapper.select:
SELECT PLAN_SEQ, USER_ID, PLAN_TYPE_CODE, PLAN_NAME, DATE_FORMAT(PLAN_DATE, '%Y-%m-%d') AS PLAN_DATE, USE_YN, DEL_YN, INS_DT, INS_IP, INS_USER_ID, UPD_DT, UPD_IP, UPD_USER_ID FROM TB_PLAN WHERE DEL_YN = 'N'
AND USER_ID = #{userId}
AND PLAN_TYPE_CODE = #{planTypeCode}
ORDER BY PLAN_DATE DESC, PLAN_SEQ DESC

mapper.insert:
INSERT INTO TB_PLAN (
    USER_ID, PLAN_TYPE_CODE, PLAN_NAME, PLAN_DATE, 
    USE_YN, DEL_YN, INS_DT, INS_IP, INS_USER_ID
) VALUES (
    #{userId}, #{planTypeCode}, #{planName}, #{planDate}, 
    COALESCE(#{useYn}, 'Y'), 'N', NOW(), #{insIp}, #{insUserId}
)

INSERT INTO TB_PLAN_DETAIL (
    PLAN_SEQ, PLAN_PHASE, PLAN_EXER_NAME, PLAN_CATEGORY_CODE, PLAN_KIND_CODE, 
    PLAN_NOTE, PLAN_REPS, PLAN_SETS, PLAN_TIME, PLAN_TOTAL_DISTANCE, PLAN_SORT_ORDER, 
    USE_YN, DEL_YN, INS_DT, INS_IP, INS_USER_ID
) VALUES (
    #{planSeq}, #{planPhase}, #{planExerName}, #{planCategoryCode}, #{planKindCode}, 
    #{planNote}, #{planReps}, #{planSets}, #{planTime}, #{planTotalDistance}, #{planSortOrder}, 
    'Y', 'N', NOW(), #{insIp}, #{insUserId}
)

mapper.update:
UPDATE TB_PLAN_DETAIL
SET DEL_YN = 'Y'
WHERE PLAN_SEQ = #{planSeq}
